#include <stdio.h>

struct Flags {
    unsigned int active : 1;
    unsigned int paid : 1;
    unsigned int attempts : 3;
};

int main(void)
{
    struct Flags flags = {.active = 1, .paid = 0, .attempts = 5};
    printf("%u %u %u\n", (unsigned int)flags.active, (unsigned int)flags.paid,
           (unsigned int)flags.attempts);
    return 0;
}

#include <stdio.h>

struct Flags {
    unsigned int active : 1;
    unsigned int paid : 1;
    unsigned int attempts : 3;
};

int main(void)
{
    struct Flags flags = {0};
    flags.active = 1;
    flags.paid = 1;
    flags.attempts = 7;
    if (flags.attempts < 7) {
        flags.attempts++;
    }
    printf("%u %u\n", (unsigned int)flags.paid, (unsigned int)flags.attempts);
    return 0;
}

#include <stdio.h>

int main(void)
{
    unsigned int active = 1, paid = 1, attempts = 5;
    unsigned int packed = active | (paid << 1) | (attempts << 2);
    printf("Packed: %u Attempts: %u\n", packed, (packed >> 2) & 7U);
    return 0;
}

